  // Return the number of distinct ways to climb n steps (1 or 2 at a time).
  return 0;
}

solution:
function ClimbStairs(n: int) -> int {
  if (n <= 2) {
    return n;
  }
  let a = 1;
  let b = 2;
  let i = 3;
  while (i <= n) {
    let c = a + b;
    a = b;
    b = c;
    i += 1;
  }
  return b;
}
